-- 13_p4_rename_runtime_uns_subordinate_objects.sql
-- P4 step 2: rename subordinate objects (constraints/indexes/sequence) on the
-- already-renamed equipment_oee_*/equipment_live_*/area_*/site_* tables so their
-- names follow the meaningful-names cutover (runtime_->oee_, uns_->live_).
-- BEHAVIOR-NEUTRAL: renames are OID-tracked (PKs used via column-inference ON
-- CONFLICT in edge-api; FKs/indexes by OID). Hardproofed: 0 fn bodies reference
-- any of these names (0 ON CONSTRAINT refs; 0 name-string refs). production_orders_runtime
-- is NOT renamed (correctly named) so its subordinate objects are left untouched.
-- Reverse: swap old<->new in each statement.
-- (replay-safe 2026-10-08: each rename is guarded — some constraints were staging-only and absent on prod.)
BEGIN;
DO $r$ BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('public.area_live_day') AND conname = 'uns_area_current_day_pkey') THEN ALTER TABLE public.area_live_day RENAME CONSTRAINT uns_area_current_day_pkey TO area_live_day_pkey; ELSE RAISE NOTICE 'skip (absent): public.area_live_day.uns_area_current_day_pkey'; END IF; END $r$;
DO $r$ BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('public.area_live_shift') AND conname = 'uns_area_current_shift_pkey') THEN ALTER TABLE public.area_live_shift RENAME CONSTRAINT uns_area_current_shift_pkey TO area_live_shift_pkey; ELSE RAISE NOTICE 'skip (absent): public.area_live_shift.uns_area_current_shift_pkey'; END IF; END $r$;
