DO $r$ BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('public.equipment_oee_shift') AND conname = 'equipment_runtime_shift_pk') THEN ALTER TABLE public.equipment_oee_shift RENAME CONSTRAINT equipment_runtime_shift_pk TO equipment_oee_shift_pk; ELSE RAISE NOTICE 'skip (absent): public.equipment_oee_shift.equipment_runtime_shift_pk'; END IF; END $r$;
